            ! --- level m = 5 ---
            v(1,1) = pref*f(5)
            v(3,1) = pay*v(1,1) + wpy*v(1,0)
            v(11,1) = qcx*v(1,1) + wqx*v(1,0)
            v(21,1) = qcy*v(1,1) + wqy*v(1,0)
            v(31,1) = qcz*v(1,1) + wqz*v(1,0)
            ! --- level m = 4 ---
