            v(3,0) = pay*v(1,0) + wpy*v(1,1)
            v(4,0) = paz*v(1,0) + wpz*v(1,1)
            v(11,0) = qcx*v(1,0) + wqx*v(1,1)
            v(21,0) = qcy*v(1,0) + wqy*v(1,1)
            v(31,0) = qcz*v(1,0) + wqz*v(1,1)
