               + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
            v(81,0) = qcy*v(31,0) + wqy*v(31,1)
            v(91,0) = qcz*v(31,0) + wqz*v(31,1) &
               + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
            ! --- level m = 3 ---
